-- Additive schema for imported source workbooks.
CREATE TABLE IF NOT EXISTS import_batches(batch_id TEXT PRIMARY KEY,file_name TEXT NOT NULL,file_sha256 TEXT NOT NULL,record_count INTEGER NOT NULL CHECK(record_count>=0),created_by INTEGER REFERENCES users(id) ON DELETE RESTRICT,status TEXT NOT NULL CHECK(status IN ('completed','failed')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))) STRICT;
CREATE TABLE IF NOT EXISTS imported_records(id INTEGER PRIMARY KEY AUTOINCREMENT,batch_id TEXT NOT NULL REFERENCES import_batches(batch_id) ON DELETE RESTRICT,sheet_type TEXT NOT NULL,source_sheet TEXT NOT NULL,source_row INTEGER NOT NULL CHECK(source_row>=2),fiscal_year INTEGER NOT NULL,currency TEXT NOT NULL CHECK(currency IN ('IRR','USD','EUR','AED','GBP')),amount_text TEXT NOT NULL,original_amount_text TEXT,original_amount_unit TEXT,foreign_amount_text TEXT,division TEXT,beneficiary_unit TEXT,requesting_unit TEXT,center_name TEXT,topic TEXT,allocation_location TEXT,allocation_type TEXT,letter_number TEXT,letter_date TEXT,budget_heading_330 TEXT,budget_heading TEXT,payment_month TEXT,other_sector_allocation TEXT,coding TEXT,performance TEXT,performance_status TEXT,description TEXT,extra_fields TEXT NOT NULL DEFAULT '{}',source_values TEXT NOT NULL DEFAULT '{}',fingerprint TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))) STRICT;
CREATE INDEX IF NOT EXISTS ix_imported_year_currency ON imported_records(fiscal_year,currency);
CREATE INDEX IF NOT EXISTS ix_imported_center ON imported_records(center_name);
CREATE INDEX IF NOT EXISTS ix_imported_fingerprint ON imported_records(fingerprint);
